#define STM32F401xE

#include "stm32f4xx.h"
#include <stdint.h>

#define MS_IN_MIN 60000.0f

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif
//this https://www.compilenrun.com/docs/iot/stm32/stm32-analog-systems/stm32-adc-configuration/
//and this helped setup the potentiometers https://davidkebo.com/microcontroller-interfacing-2/
//i will use this later in the other part of lab too
void config(){
	    //GPIO clocks
	    RCC->AHB1ENR |= (1 << 0) | (1 << 1);
	    //set up as analog on pins 0, 1 on port
	    GPIOA->MODER |= ((3 << 0) | (3 << 2));
	    //clear the pullup and pull down
	    GPIOA->PUPDR &= ~((3 << 0) | (3 << 2));
	    //set PB5 to alternate mode
	    GPIOB->MODER &= ~(3 << 10);
	    GPIOB->MODER |=  (2 << 10);
	    //APB2ENR to enable the ADC1 channel
	    RCC->APB2ENR |= RCC_APB2ENR_ADC1EN;
	    //ADC prescaler to the maximum of 16mhz/4 = 4 mhz
	    ADC->CCR &= ~(3 << 16);
	    ADC->CCR |=  (1 << 16);
	    //using the default 12-bit resolution
	    ADC1->CR1 = 0;
	    //alignment
	    ADC1->CR2 = 0;
	    //according to article this sequence the registers to configure the number of channels to sample. this is set to 1
	    ADC1->SQR1 = 0;
	    ADC1->SQR3 = 0;
	    //sampling time to 1 to 84 cycles clear then set
	    ADC1->SMPR2 &= ~((7 << 0) | (7 << 3));
	    ADC1->SMPR2 |=  ((4 << 0) | (4 << 3));
	    //enable ADC1
	    ADC1->CR2 |= ADC_CR2_ADON;
	    //select AF2 channel selection
	    GPIOB->AFR[0] &= ~(0xF << 20);
	    GPIOB->AFR[0] |=  (2 << 20);
	    //this helped me trigger the conversion
	    ADC1->CR2 &= ~(ADC_CR2_CONT | ADC_CR2_EXTEN);
	    //enable TIM3 clock
	    RCC->APB1ENR |= RCC_APB1ENR_TIM3EN;
	    //stop timer
	    TIM3->CR1 = 0;
	    //1 MHz
	    TIM3->PSC = 15;
	    //1 kHz
	    TIM3->ARR = 999;
	    //50% duty cycle
	    TIM3->CCR2 = 500;
	    //configure channel 2 for PWM mode 1
	    TIM3->CCMR1 &= ~(3 << 8);
	    TIM3->CCMR1 &= ~(7 << 12);
	    TIM3->CCMR1 |=  (6 << 12);
	    TIM3->CCMR1 |= TIM_CCMR1_OC2PE;
	    //enable channel 2 output
	    TIM3->CCER |= TIM_CCER_CC2E;
	    //enable preload
	    TIM3->CR1 |= TIM_CR1_ARPE;
	    //event registers
	    TIM3->EGR = TIM_EGR_UG;
	    //start timer
	    TIM3->CR1 |= TIM_CR1_CEN;
	    //TIM5 clock
	    RCC->APB1ENR |= (1 << 3);
	    //TIM5 configuration
	    TIM5->PSC = 15999;
	    TIM5->ARR = 0xFFFFFFFF;
	    TIM5->EGR = TIM_EGR_UG;
	    TIM5->SR = 0;
	    TIM5->CNT = 0;
	    TIM5->CR1 |= TIM_CR1_CEN;
	    //SYSCFG clock
	    RCC->APB2ENR |= RCC_APB2ENR_SYSCFGEN;
}
uint16_t readAdcPin(uint8_t pin) {
    //get the channel using pin
    ADC1->SQR3 = pin;
    //start the conversion
    ADC1->CR2 |= ADC_CR2_SWSTART;
    //according to the article i should wait for conversion so this is copy and pasted here
    while (!(ADC1->SR & ADC_SR_EOC)){};
    //this will return the ADC result
    return ADC1->DR;
}
int main(void) {
	config();
	TIM3->CCR2 = 0;
	uint16_t freq1;
	uint16_t freq2;
	uint32_t timestamp = TIM5->CNT;
	//10 ms wait
	while((TIM5->CNT - timestamp) < 10){}
	while(1){
		freq1 = readAdcPin(0);
		//i added by one so i can use the division optimization using >> 12
		freq2 = (readAdcPin(1) + 1);
		//500 hz mininum and volume must be above 250
		if(freq1 > 499 && freq2 > 250){
			// counter frequecny divided by our notes frequncy (1mhz / frequency) -1
			TIM3->ARR = (1000000 / freq1) - 1;
			//powermode is determined here
			TIM3->CCR2 = ((TIM3->ARR + 1) * freq2) >> 12;
			//event sent immediately in TIM3
			TIM3->EGR = TIM_EGR_UG;
		}else{
			TIM3->CCR2 = 0;
		}
		//10 ms wait
		timestamp = TIM5->CNT;
		while((TIM5->CNT - timestamp) < 10){}
	}
}
